beforeExample:
package test;

class Parent {
    public void doSomething() {}
}

class MyClass extends Parent implements Runnable {
    @Override
    public void doSomething() {
        System.out.println("Overriding");
    }

    public void run() {
        System.out.println("Running");
    }
}

